// Ported from the Node app's Sequelize model ApplicationDocument (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class ApplicationDocumentConfiguration : IEntityTypeConfiguration<ApplicationDocument>
{
    public void Configure(EntityTypeBuilder<ApplicationDocument> builder)
    {
        builder.ToTable("application_documents");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.AdmissionId).HasColumnName("admission_id");
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.OriginalName).HasColumnName("original_name").HasColumnType("nvarchar(255)").HasMaxLength(255).IsRequired();
        builder.Property(e => e.MimeType).HasColumnName("mime_type").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Size).HasColumnName("size");
        builder.Property(e => e.Data).HasColumnName("data").HasColumnType("nvarchar(max)").IsRequired();
        builder.Property(e => e.UploadedByName).HasColumnName("uploaded_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
    }
}
